#pragma once
// HTTP transport and static asset serving.
std::string mimeFor(const std::string& p){if(p.size()>3&&p.substr(p.size()-3)==".js")return "application/javascript";if(p.size()>4&&p.substr(p.size()-4)==".css")return "text/css";return "text/html; charset=utf-8";}
void handle(Socket c){std::string req;char buf[8192];size_t headerEnd=std::string::npos;while(req.size()<1048576){int n=recv(c,buf,sizeof(buf),0);if(n<=0)break;req.append(buf,n);headerEnd=req.find("\r\n\r\n");if(headerEnd!=std::string::npos)break;}if(headerEnd==std::string::npos){closeSocket(c);return;}std::istringstream line(req.substr(0,req.find("\r\n")));std::string method,path,version;line>>method>>path>>version;size_t len=0;std::string token;std::istringstream headers(req.substr(req.find("\r\n")+2,headerEnd));std::string h;while(std::getline(headers,h)){if(!h.empty()&&h.back()=='\r')h.pop_back();auto pos=h.find(':');if(pos==std::string::npos)continue;auto key=h.substr(0,pos),val=h.substr(pos+1);while(!val.empty()&&val[0]==' ')val.erase(0,1);std::transform(key.begin(),key.end(),key.begin(),[](unsigned char x){return std::tolower(x);});if(key=="content-length"){auto parsed=nexus::http::parseContentLength(val);len=parsed.value_or(1048577);}if(key=="authorization"&&val.rfind("Bearer ",0)==0)token=val.substr(7);}int code=200;std::string mime,body;if(!nexus::api::isSupportedMethod(method)||!nexus::api::isValidHttpVersion(version)){code=400;body="{\"error\":\"Invalid HTTP request\"}";mime="application/json";}else if(len>524288){code=413;body="{}";mime="application/json";}else{std::string payload=req.substr(headerEnd+4);while(payload.size()<len){int n=recv(c,buf,std::min(sizeof(buf),len-payload.size()),0);if(n<=0)break;payload.append(buf,n);}if(payload.size()!=len){code=400;body="{\"error\":\"Incomplete request body\"}";mime="application/json";}else if(nexus::api::isApiPath(path))body=response(method,path,payload,token,code,mime);else{std::string file=path=="/"?"index.html":path.substr(1);if(!nexus::http::safeAssetPath(path)){code=403;body="Forbidden";}else{std::ifstream in(fs::path(NEXUS_WEB_DIR)/file,std::ios::binary);if(!in){code=404;body="Not found";}else body.assign(std::istreambuf_iterator<char>(in),{});}mime=mimeFor(file);}}std::string status=nexus::http::statusText(code);std::ostringstream out;out<<"HTTP/1.1 "<<code<<' '<<status<<"\r\nContent-Type: "<<mime<<"\r\nX-Content-Type-Options: nosniff\r\nX-Frame-Options: DENY\r\nContent-Security-Policy: default-src 'self'; script-src 'self'; style-src 'self' 'unsafe-inline'; img-src 'self' data:; connect-src 'self'; object-src 'none'; base-uri 'none'; frame-ancestors 'none'\r\nReferrer-Policy: no-referrer\r\nCache-Control: no-store\r\nContent-Length: "<<body.size()<<"\r\nConnection: close\r\n\r\n"<<body;auto data=out.str();size_t offset=0;while(offset<data.size()){int n=send(c,data.data()+offset,(int)std::min<size_t>(32768,data.size()-offset),0);if(n<=0)break;offset+=n;}closeSocket(c);}
